def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Fraud, Identity Theft, and Other Reports by Military Consumers.csv"
    # File has a blank first row; real header row begins on the second row.
    return pd.read_csv(path, header=1)

def process(fraudByMilitary2024) -> pd.DataFrame:
    import pandas as pd

    raw = fraudByMilitary2024.copy()

    # Locate header row
    header_idx = None
    for i in range(len(raw)):
        row = raw.iloc[i].astype(str).str.strip().tolist()
        if any(cell == 'Military Status' for cell in row):
            header_idx = i
            break
    if header_idx is None:
        return pd.DataFrame([{
            'error': "Could not locate header row containing 'Military Status'",
            'first_rows_col0': raw.iloc[:6, 0].astype(str).tolist()
        }])

    df = raw.iloc[header_idx:].copy()
    df.columns = df.iloc[0].astype(str).str.strip().tolist()
    df = df.iloc[1:].copy()

    # Drop fully empty rows
    df = df.dropna(how='all').copy()

    # Require a status label
    if 'Military Status' not in df.columns:
        return pd.DataFrame([{'error': "Header set but 'Military Status' column still missing", 'columns': df.columns.tolist()}])

    df = df[df['Military Status'].notna()].copy()
    df['Military Status'] = df['Military Status'].astype(str).str.strip()

    # Drop footer/source rows
    df = df[~df['Military Status'].str.contains(r'^Source:', regex=True, na=False)].copy()

    # Parse Median Fraud Loss to numeric
    if 'Median Fraud Loss' not in df.columns:
        return pd.DataFrame([{'error': "'Median Fraud Loss' column missing", 'columns': df.columns.tolist()}])

    df['Median Fraud Loss'] = (
        df['Median Fraud Loss']
        .astype(str)
        .str.replace(r'[^0-9.\-]', '', regex=True)
    )
    df['Median Fraud Loss'] = pd.to_numeric(df['Median Fraud Loss'], errors='coerce')

    # Keep only service-branch rows: match either exact branch name or labels like
    # 'Active Duty: Army' / 'Veteran: Navy'
    branches = ['Army', 'Navy', 'Air Force', 'Marine Corps', 'Coast Guard', 'Space Force']
    ms = df['Military Status']

    def extract_branch(label: str):
        s = str(label).strip()
        for b in branches:
            if s == b:
                return b
            if s.endswith(': ' + b) or s.endswith(':' + b):
                return b
            if s.endswith(b) and (s.startswith('Active Duty') or s.startswith('Veteran') or s.startswith('Reserve') or s.startswith('National Guard')):
                return b
        return None

    df['_branch'] = ms.map(extract_branch)

    candidates = df.dropna(subset=['_branch', 'Median Fraud Loss']).copy()

    if candidates.empty:
        # Debug view: show what labels exist and their parsed loss
        dbg = df[['Military Status', 'Median Fraud Loss']].copy()
        return dbg.head(30)

    out = (
        candidates.sort_values('Median Fraud Loss', ascending=False)
        .head(1)
        .reset_index(drop=True)
    )

    # Return exact label format from the data
    return out[['Military Status', 'Median Fraud Loss']]

def process(medianFraudLossByBranch) -> pd.DataFrame:
    import pandas as pd

    df = medianFraudLossByBranch.copy()

    # Branch rows are the ones that are just the branch name (as shown in the table)
