def process(medianFraudLossByBranch) -> pd.DataFrame:
    import pandas as pd
    import re

    df = medianFraudLossByBranch.copy()

    # Defensive: ensure expected columns exist
    if 'Military Status' not in df.columns or 'Median Fraud Loss' not in df.columns:
        return pd.DataFrame([{
            'error': 'Expected columns not found',
            'columns': df.columns.tolist()
        }])

    df['Military Status'] = df['Military Status'].astype(str)

    branches = ['Army', 'Navy', 'Air Force', 'Marine Corps', 'Coast Guard', 'Space Force']

    # Prefer exact branch rows
    branch_rows = df[df['Military Status'].isin(branches)].copy()

    # If exact-branch rows are not present (table structure differs), fall back to labels ending with ': <Branch>'
    if branch_rows.empty:
        pattern = r'(?::\s*)(' + '|'.join([re.escape(b) for b in branches]) + r')$'
        tmp = df[df['Military Status'].str.contains(pattern, regex=True, na=False)].copy()
        if not tmp.empty:
            tmp['Military Status'] = tmp['Military Status'].str.extract(pattern, expand=False)
            branch_rows = tmp[['Military Status', 'Median Fraud Loss']].copy()

    if branch_rows.empty:
        return pd.DataFrame([{
            'error': 'No branch rows found',
            'unique_military_status': sorted(df['Military Status'].unique().tolist())
        }])

    # Make sure Median Fraud Loss is numeric
    branch_rows['Median Fraud Loss'] = pd.to_numeric(branch_rows['Median Fraud Loss'], errors='coerce')

    out = branch_rows.sort_values('Median Fraud Loss', ascending=False).head(1).reset_index(drop=True)
    return out[['Military Status', 'Median Fraud Loss']]

